/* === OFFLINE SAVE GAME EXPORT & IMPORT UTILITIES === */
window.exportSaveGameOffline = function() {
try {
const saveKeys = Object.keys(localStorage).filter(k => k.includes("bmi_save_") || k.includes("bms_save_") || k === "bus_manager_indonesia_save");
const exportData = {};
saveKeys.forEach(k => {
exportData[k] = localStorage.getItem(k);
});
const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(exportData, null, 2));
const dlAnchor = document.createElement('a');
dlAnchor.setAttribute("href", dataStr);
dlAnchor.setAttribute("download", `bmi_backup_${new Date().toISOString().slice(0,10)}.json`);
document.body.appendChild(dlAnchor);
dlAnchor.click();
dlAnchor.remove();
alert("✅ Berkas simpanan game (JSON) berhasil diunduh secara offline!");
} catch (err) {
alert("⚠️ Gagal mengekspor data simpanan: " + err.message);
}
};
window.importSaveGameOffline = function(jsonStr) {
try {
const data = JSON.parse(jsonStr);
let count = 0;
Object.keys(data).forEach(k => {
localStorage.setItem(k, data[k]);
count++;
});
alert(`✅ Berhasil memulihkan ${count} berkas simpanan game! Silakan muat ulang halaman.`);
window.location.reload();
} catch (err) {
alert("⚠️ Gagal mengimpor berkas simpanan: " + err.message);
}
};
